function flatten(obj, prefix = '') {
  return Object.entries(obj).reduce((acc, [k, v]) => {
    const key = prefix ? prefix + '.' + k : k;
    if (typeof v === 'object' && v !== null && !Array.isArray(v)) {
      return {...acc, ...flatten(v, key)};
    }
    return {...acc, [key]: v};
  }, {});
}
console.log(flatten({a: {b: 1, c: {d: 2}}}));

